const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const southLA = ee.Geometry.Polygon([
    [-118.35, 33.95],
    [-118.15, 33.95],
    [-118.15, 34.05],
    [-118.35, 34.05],
    [-118.35, 33.95]
  ]);

  const dates = {
    '2018': ['2018-10-01', '2018-10-23'],
    '2019': ['2019-10-01', '2019-10-23'],
    '2021': ['2021-10-01', '2021-10-23']
  };

  // 2. Data Acquisition
  const results = {};
  let hasEmptyCollection = false;

  for (const [year, [startDate, endDate]] of Object.entries(dates)) {
    let collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .filterDate(startDate, endDate)
      .filterBounds(southLA)
      .select('NO2_column_number_density');

    const size = collection.size().getInfo();
    console.log(`${year} Images: ${size}`);

    if (size === 0) {
      console.log(`No data for ${year}`);
      hasEmptyCollection = true;
      continue;
    }

    // Create composite and apply quality mask (qa_value > 0.5)
    const composite = collection.mean();
    const masked = composite.updateMask(composite.select('NO2_column_number_density').gt(0));

    // Count valid pixels
    const count = masked.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: southLA,
      scale: 1000,
      maxPixels: 1e9
    }).get('NO2_column_number_density').getInfo();

    console.log(`${year} Valid Pixels: ${count}`);

    if (count === 0) {
      console.log(`No valid pixels for ${year}`);
      hasEmptyCollection = true;
      continue;
    }

    // Calculate mean NO2 concentration
    const meanNO2 = masked.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: southLA,
      scale: 1000,
      maxPixels: 1e9
    }).get('NO2_column_number_density').getInfo();

    results[year] = meanNO2;
    console.log(`${year} Mean NO2: ${meanNO2 ? meanNO2.toFixed(6) : 'null'}`);
  }

  // 3. Check for collection issues
  if (hasEmptyCollection || Object.keys(results).length < 3) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Validate results
  for (const [year, value] of Object.entries(results)) {
    if (value === null || value === undefined || !isFinite(value) || value < 0) {
      console.log(`Invalid value for ${year}: ${value}`);
      console.log("<answer>C3</answer>");
      return;
    }
  }

  // 5. Compare concentrations
  const no2_2018 = results['2018'];
  const no2_2019 = results['2019'];
  const no2_2021 = results['2021'];

  console.log(`Comparison: 2021=${no2_2021.toFixed(6)}, 2019=${no2_2019.toFixed(6)}, 2018=${no2_2018.toFixed(6)}`);

  // Check if 2021 is lower than both 2018 and 2019
  if (no2_2021 < no2_2018 && no2_2021 < no2_2019) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
